import { Component, JSX, splitProps } from 'solid-js';

export interface NumberTickerProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const NumberTicker: Component<NumberTickerProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <div
      class={`inline-block tabular-nums font-bold tracking-tight text-foreground ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

